// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, random, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');
const loadInter = makeLoadFont('Inter');

// Library: none — native interpolate/spring for smooth motion choreography

const { fontFamily: montserrat } = loadMontserrat();
const { fontFamily: inter } = loadInter();



export type PrizeDrawProps = Record<string, any>;

const formatCurrency = (val: number) => "£" + val.toLocaleString("en-GB", { minimumFractionDigits: 0, maximumFractionDigits: 0 });
const formatCurrencyDecimals = (val: number) => "£" + val.toLocaleString("en-GB", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const TickIcon: React.FC<{ size: number }> = ({ size }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" style={{ transition: "none" }}>
    <circle cx="12" cy="12" r="12" fill="#22C55E" />
    <path d="M7 12l3 3 7-7" stroke="white" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" fill="none" />
  </svg>
);

const BankIcon: React.FC<{ size: number }> = ({ size }) => (
  <svg width={size} height={size} viewBox="0 0 100 100" style={{ transition: "none" }}>
    <polygon points="50,15 10,45 90,45" fill="#CBD5E1" />
    <rect x="22" y="50" width="12" height="30" fill="#94A3B8" />
    <rect x="44" y="50" width="12" height="30" fill="#94A3B8" />
    <rect x="66" y="50" width="12" height="30" fill="#94A3B8" />
    <rect x="10" y="80" width="80" height="10" fill="#CBD5E1" />
  </svg>
);

const NoteIcon: React.FC = () => (
  <svg viewBox="0 0 120 70" width="100%" height="100%" style={{ transition: "none" }}>
    <rect x="0" y="0" width="120" height="70" rx="8" fill="#2D334A" />
    <rect x="5" y="5" width="110" height="60" rx="4" fill="none" stroke="#4A5568" strokeWidth="2" />
    <circle cx="60" cy="35" r="18" fill="#1A2035" />
    <text x="60" y="47" fontSize="30" fontFamily={montserrat} fontWeight="bold" fill="#4A5568" textAnchor="middle">£</text>
  </svg>
);

const CoinIcon: React.FC = () => (
  <svg viewBox="0 0 100 100" width="100%" height="100%" style={{ transition: "none" }}>
    <circle cx="50" cy="50" r="48" fill="#F2C14E" />
    <circle cx="50" cy="50" r="38" fill="none" stroke="#D4A017" strokeWidth="3" />
    <text x="50" y="68" fontSize="50" fontFamily={montserrat} fontWeight="bold" fill="#B8860B" textAnchor="middle">£</text>
  </svg>
);

const MainCoinFront: React.FC = () => {
  const stars = [];
  for (let i = 0; i < 12; i++) {
    const angle = (i * 30 * Math.PI) / 180;
    const x = 100 + 82 * Math.cos(angle);
    const y = 100 + 82 * Math.sin(angle);
    stars.push(
      <text key={i} x={x} y={y + 5} fontSize="14" fill="#C49010" textAnchor="middle" fontFamily={inter}>★</text>
    );
  }
  return (
    <svg viewBox="0 0 200 200" width="100%" height="100%" style={{ transition: "none" }}>
      <circle cx="100" cy="100" r="98" fill="#F2C14E" />
      <circle cx="100" cy="100" r="90" fill="#E8B031" />
      <circle cx="100" cy="100" r="75" fill="none" stroke="#C49010" strokeWidth="4" strokeDasharray="6 6" />
      {stars}
      <text x="100" y="140" fontSize="110" fontFamily={montserrat} fontWeight="900" fill="#C49010" textAnchor="middle">£</text>
    </svg>
  );
};

const PrizeDraw: React.FC<PrizeDrawProps> = ({
  backgroundColor = "#12172B",
  transparentBackground = false,
  durationInSeconds = 6,
  goldAccent = "#F2C14E",
  prizeAmount = 1000,
  winAmount = 100,
  topPrizeText = "TOP PRIZE",
  paidText = "PAID STRAIGHT\nINTO YOUR BANK",
  headsText = "HEADS",
  orText = "- OR -",
  tailsText = "TAILS",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Pre-generate background floating items
  const floatingItems = useMemo(() => {
    return Array.from({ length: 15 }).map((_, i) => ({
      id: i,
      x: 0.1 + random(`fx${i}`) * 0.8,
      delay: random(`fdelay${i}`) * 20,
      speed: 0.8 + random(`fspeed${i}`) * 1.5,
      size: 40 + random(`fsize${i}`) * 40,
      isNote: random(`ftype${i}`) > 0.4,
      rotStart: random(`frot${i}`) * 360,
      rotSpeed: -3 + random(`frots${i}`) * 6,
      depth: random(`fdepth${i}`)
    }));
  }, []);

  // SCENE 1: Count Up (Frames 0 - 55)
  const s1TextScale = interpolate(spring({ frame, fps, config: { damping: 12 } }), [0, 1], [0, 1]);
  const s1TextExitScale = interpolate(frame, [45, 55], [1, 0.4], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const finalS1Scale = frame < 45 ? s1TextScale : s1TextScale * s1TextExitScale;
  const s1TextY = interpolate(frame, [45, 55], [height / 2, height / 2 + 100 * s], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const s1TextOpacity = interpolate(frame, [45, 55], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const countValue = Math.floor(interpolate(frame, [0, 30], [0, prizeAmount], { extrapolateRight: "clamp" }));

  const cap1Entry = interpolate(frame, [10, 20], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const cap1Opacity = cap1Entry * s1TextOpacity;
  const cap1Y = height / 2 + 150 * s + interpolate(frame, [10, 20], [20 * s, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const floatingOpacityBase = interpolate(frame, [40, 50], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // SCENE 2: Phone Mockup (Frames 45 - 105)
  const phoneSpring = spring({ frame: frame - 45, fps, config: { damping: 14 } });
  const phoneExit = interpolate(frame, [95, 105], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const phoneY = interpolate(phoneSpring, [0, 1], [height + 500 * s, height / 2]) + phoneExit * (height / 2 + 500 * s);
  const phoneOpacity = frame < 45 ? 0 : 1;

  const notifySpring = spring({ frame: frame - 55, fps, config: { damping: 12 } });
  const notifyY = interpolate(notifySpring, [0, 1], [-150 * s, 40 * s]);
  const notifyOpacity = frame < 55 ? 0 : 1;

  const balanceTick = Math.floor(interpolate(frame, [70, 85], [0, prizeAmount], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }));
  const currentBalance = 250 + balanceTick;

  const plusSpring = spring({ frame: frame - 65, fps, config: { damping: 12 } });
  const plusY = interpolate(plusSpring, [0, 1], [20 * s, 0]);
  const plusOpacity = frame < 65 ? 0 : interpolate(plusSpring, [0, 1], [0, 1]);

  const cap2Spring = spring({ frame: frame - 60, fps, config: { damping: 12 } });
  const cap2Enter = interpolate(cap2Spring, [0, 1], [0, 1]);
  const cap2Exit = interpolate(frame, [95, 105], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const cap2Opacity = frame < 60 ? 0 : cap2Enter * cap2Exit;
  const cap2Y = interpolate(cap2Spring, [0, 1], [height / 2 + 550 * s, height / 2 + 500 * s]);

  // SCENE 3: Coin Flip (Frames 100 - 180)
  const headsSpring = spring({ frame: frame - 100, fps, config: { damping: 12 } });
  const headsOpacity = frame < 100 ? 0 : interpolate(headsSpring, [0, 0.5], [0, 1], { extrapolateRight: "clamp" });
  const headsY = interpolate(headsSpring, [0, 1], [height / 2 - 400 * s, height / 2 - 250 * s]);

  const coinRotT = Math.max(0, Math.min(1, (frame - 105) / 40));
  const easeOutRot = 1 - Math.pow(1 - coinRotT, 3);
  const rotateX = easeOutRot * 1440;
  const coinHop = Math.sin(coinRotT * Math.PI) * 350 * s;
  const coinBaseY = interpolate(
    spring({ frame: frame - 105, fps, config: { damping: 15 } }),
    [0, 1],
    [height + 200 * s, height / 2 + 100 * s]
  );
  const finalCoinY = coinBaseY - coinHop;
  const coinOpacity = frame < 105 ? 0 : 1;

  const ripple1Scale = interpolate(frame, [145, 175], [0.5, 2], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const ripple1Opacity = interpolate(frame, [145, 150, 175], [0, 0.8, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const ripple2Scale = interpolate(frame, [155, 185], [0.5, 2], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const ripple2Opacity = interpolate(frame, [155, 160, 185], [0, 0.6, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const bonusSpring = spring({ frame: frame - 145, fps, config: { damping: 10 } });
  const bonusScale = interpolate(bonusSpring, [0, 1], [0, 1]);
  const bonusOpacity = interpolate(frame, [145, 148], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden", fontFamily: montserrat, transition: "none" }}>
      {/* Background Glow */}
      <div style={{
        position: "absolute",
        left: "50%",
        top: "50%",
        width: "150%",
        height: "150%",
        transform: "translate(-50%, -50%)",
        background: `radial-gradient(circle, ${goldAccent} 0%, transparent 60%)`,
        opacity: 0.15,
        transition: "none"
      }} />

      {/* Floating Items */}
      {floatingItems.map((item) => {
        const t = frame - item.delay;
        const y = height + 100 - t * item.speed * 10 * s;
        const rot = item.rotStart + t * item.rotSpeed;
        const itemOpacity = floatingOpacityBase * (0.6 * item.depth + 0.2);
        
        return (
          <div key={item.id} style={{
            position: "absolute",
            left: item.x * width,
            top: y,
            transform: `translate(-50%, -50%) rotate(${rot}deg)`,
            opacity: t < 0 ? 0 : itemOpacity,
            width: item.size * s,
            height: item.size * s,
            filter: `blur(${(1 - item.depth) * 4}px)`,
            transition: "none"
          }}>
            {item.isNote ? <NoteIcon /> : <CoinIcon />}
          </div>
        );
      })}

      {/* Main Count Text */}
      <div style={{
        position: "absolute",
        width: "100%",
        top: s1TextY,
        transform: `translateY(-50%) scale(${finalS1Scale})`,
        opacity: s1TextOpacity,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        transition: "none"
      }}>
        <h1 style={{
          fontSize: 180 * s,
          margin: 0,
          color: goldAccent,
          textShadow: `0 10px 30px rgba(242, 193, 78, 0.3)`,
          lineHeight: 1,
          transition: "none"
        }}>
          {formatCurrency(countValue)}
        </h1>
      </div>

      {/* Caption 1 */}
      <div style={{
        position: "absolute",
        width: "100%",
        top: cap1Y,
        opacity: cap1Opacity,
        display: "flex",
        justifyContent: "center",
        transition: "none"
      }}>
        <p style={{
          fontSize: 40 * s,
          letterSpacing: 4 * s,
          margin: 0,
          color: "white",
          transition: "none"
        }}>{topPrizeText}</p>
      </div>

      {/* Phone Mockup */}
      <div style={{
        position: "absolute",
        left: width / 2,
        top: phoneY,
        transform: "translate(-50%, -50%)",
        width: 460 * s,
        height: 900 * s,
        backgroundColor: "#0F172A",
        borderRadius: 60 * s,
        border: `${8 * s}px solid #1E293B`,
        boxShadow: `0 30px 60px rgba(0,0,0,0.5)`,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        padding: 40 * s,
        boxSizing: "border-box",
        opacity: phoneOpacity,
        transition: "none"
      }}>
        {/* Phone Notch */}
        <div style={{
          position: "absolute",
          top: 0,
          width: 150 * s,
          height: 30 * s,
          backgroundColor: "#1E293B",
          borderBottomLeftRadius: 20 * s,
          borderBottomRightRadius: 20 * s,
          transition: "none"
        }} />

        {/* Screen Content */}
        <div style={{ marginTop: 180 * s, display: "flex", flexDirection: "column", alignItems: "center", transition: "none" }}>
          <p style={{ fontSize: 24 * s, color: "#94A3B8", margin: 0, fontFamily: inter, transition: "none" }}>CURRENT BALANCE</p>
          <p style={{ fontSize: 55 * s, color: "white", margin: `${10 * s}px 0 0 0`, fontWeight: "bold", transition: "none" }}>
            {formatCurrencyDecimals(currentBalance)}
          </p>
          
          <p style={{
            fontSize: 32 * s,
            color: "#22C55E",
            margin: `${10 * s}px 0 0 0`,
            fontWeight: "bold",
            opacity: plusOpacity,
            transform: `translateY(${plusY}px)`,
            transition: "none"
          }}>
            + {formatCurrencyDecimals(prizeAmount)}
          </p>

          <div style={{ marginTop: 80 * s, transition: "none" }}>
            <BankIcon size={120 * s} />
          </div>
        </div>

        {/* Notification Banner */}
        <div style={{
          position: "absolute",
          top: notifyY,
          width: 400 * s,
          height: 90 * s,
          backgroundColor: "white",
          borderRadius: 25 * s,
          boxShadow: `0 10px 25px rgba(0,0,0,0.2)`,
          display: "flex",
          alignItems: "center",
          padding: `0 ${20 * s}px`,
          boxSizing: "border-box",
          opacity: notifyOpacity,
          transition: "none"
        }}>
          <TickIcon size={40 * s} />
          <div style={{ marginLeft: 15 * s, display: "flex", flexDirection: "column", transition: "none" }}>
            <p style={{ margin: 0, fontSize: 22 * s, fontWeight: "bold", color: "#0F172A", transition: "none" }}>{formatCurrency(prizeAmount)} received</p>
            <p style={{ margin: 0, fontSize: 18 * s, color: "#64748B", fontFamily: inter, transition: "none" }}>Payment received</p>
          </div>
        </div>
      </div>

      {/* Caption 2 */}
      <div style={{
        position: "absolute",
        width: "100%",
        top: cap2Y,
        opacity: cap2Opacity,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        transition: "none"
      }}>
        {paidText.split("\n").map((line, i) => (
          <p key={i} style={{
            fontSize: 45 * s,
            margin: `${4 * s}px 0`,
            color: "white",
            fontWeight: "bold",
            lineHeight: 1.1,
            transition: "none"
          }}>{line}</p>
        ))}
      </div>

      {/* Heads or Tails Title */}
      <div style={{
        position: "absolute",
        width: "100%",
        top: headsY,
        opacity: headsOpacity,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        transition: "none"
      }}>
        <h2 style={{ fontSize: 90 * s, margin: 0, color: "white", lineHeight: 1, transition: "none" }}>{headsText}</h2>
        
        <div style={{ display: "flex", alignItems: "center", margin: `${15 * s}px 0`, transition: "none" }}>
          <div style={{ width: 60 * s, height: 2 * s, backgroundColor: goldAccent, transition: "none" }} />
          <span style={{ margin: `0 ${20 * s}px`, fontSize: 35 * s, color: goldAccent, fontWeight: "bold", letterSpacing: 2, transition: "none" }}>{orText}</span>
          <div style={{ width: 60 * s, height: 2 * s, backgroundColor: goldAccent, transition: "none" }} />
        </div>

        <h2 style={{ fontSize: 90 * s, margin: 0, color: goldAccent, lineHeight: 1, transition: "none" }}>{tailsText}</h2>
      </div>

      {/* Impact Ripples */}
      <div style={{
        position: "absolute",
        left: width / 2,
        top: height / 2 + 100 * s,
        transform: "translate(-50%, -50%)",
        width: 300 * s * ripple1Scale,
        height: 100 * s * ripple1Scale,
        borderRadius: "50%",
        border: `3px solid ${goldAccent}`,
        opacity: ripple1Opacity,
        transition: "none"
      }} />
      <div style={{
        position: "absolute",
        left: width / 2,
        top: height / 2 + 100 * s,
        transform: "translate(-50%, -50%)",
        width: 300 * s * ripple2Scale,
        height: 100 * s * ripple2Scale,
        borderRadius: "50%",
        border: `3px solid ${goldAccent}`,
        opacity: ripple2Opacity,
        transition: "none"
      }} />

      {/* Flipping Coin */}
      <div style={{
        position: "absolute",
        left: width / 2,
        top: finalCoinY,
        width: 0,
        height: 0,
        perspective: 1000 * s,
        opacity: coinOpacity,
        transition: "none"
      }}>
        <div style={{
          position: "absolute",
          left: -120 * s,
          top: -120 * s,
          width: 240 * s,
          height: 240 * s,
          transform: `rotateX(${rotateX}deg)`,
          transformStyle: "preserve-3d",
          transition: "none"
        }}>
          <div style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            backfaceVisibility: "hidden",
            filter: `drop-shadow(0 15px 20px rgba(0,0,0,0.4))`,
            transition: "none"
          }}>
            <MainCoinFront />
          </div>
          <div style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            backfaceVisibility: "hidden",
            transform: "rotateX(180deg)",
            filter: `drop-shadow(0 -15px 20px rgba(0,0,0,0.4))`,
            transition: "none"
          }}>
            <MainCoinFront />
          </div>
        </div>
      </div>

      {/* Bonus Text */}
      <div style={{
        position: "absolute",
        left: width / 2 + 180 * s,
        top: height / 2 + 100 * s,
        transform: `translateY(-50%) scale(${bonusScale})`,
        opacity: bonusOpacity,
        transition: "none"
      }}>
        <p style={{
          fontSize: 70 * s,
          color: goldAccent,
          fontWeight: "bold",
          margin: 0,
          textShadow: `0 5px 15px rgba(0,0,0,0.5)`,
          transition: "none"
        }}>
          +{formatCurrency(winAmount)}
        </p>
      </div>

    </AbsoluteFill>
  );
};

export default PrizeDraw;